01:-:-:-:6      IADD bar_t, pidx, bar_t;
--:-:-:-:6      ISETP.LT.U32.AND P3, PT, bar_t, nph, PT;
--:-:-:-:6      SHL op, lane, 0x2;
--:-:-:-:6      NOP;
--:-:-:-:6      NOP;
